import {clone,uid,linked,point} from './core.js';
import {modifier} from './effects.js';
import {ensureEdges,edgeSelected} from './edges.js';
import {insertDocumentObjects,modifyDocument} from './document-commands.js';

export function mirroredEdges(o,ids,axis){if(!ids?.length||!o.symmetry)return ids||[];ensureEdges(o);const w=o.nodes.map(n=>point(o.matrix,n)),result=new Set(ids),equal=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y)<1;for(let i=0;i<o.nodes.length-(o.closed?0:1);i++){if(!edgeSelected(o.nodes[i],ids))continue;const a={x:2*axis-w[i].x,y:w[i].y},b={x:2*axis-w[(i+1)%w.length].x,y:w[(i+1)%w.length].y};for(let j=0;j<w.length-(o.closed?0:1);j++)if(equal(a,w[j])&&equal(b,w[(j+1)%w.length])||equal(b,w[j])&&equal(a,w[(j+1)%w.length]))result.add(o.nodes[j].edgeId);}return [...result];}
function mapEdges(from,to,ids){return ids?.map(id=>{const index=from.nodes.findIndex(n=>edgeSelected(n,[id]));return to.nodes[index]?.edgeId;}).filter(Boolean)||[];}
export function operationTargets(p,view,selected,ranges={},mutate=false){const os=p.views[view],result=new Map();for(const id of selected){let o=os.find(o=>o.id===id);if(o?.source)o=os.find(s=>s.id===o.source);if(o?.type!=='path'||o.locked)continue;let ids=ranges[o.id]||[];if(p.liveMirror){const master=os.find(s=>s.id===o.instanceOf);if(master){ids=mapEdges(o,master,ids);o=master;}ids=mirroredEdges(o,ids,p.centerAxis??350);}
const previous=result.get(o.id);if(previous)previous.edgeIds=[...new Set([...previous.edgeIds,...ids])];else result.set(o.id,{o,edgeIds:ids});}return [...result.values()];}
export function addConstructions(p,view,selected,type,params={},ranges={}){return modifyDocument(p,view,()=>{const results=[];for(const {o,edgeIds} of operationTargets(p,view,selected,ranges,true)){const n=linked(o,type,{...params,position:params.position||'inside',...(edgeIds.length?{edgeIds}:{}),operationId:uid()});insertDocumentObjects(p,view,[n],{command:'construction:'+type});results.push(n.id);}return results;},{command:'construction:'+type});}
export function addModifiers(p,view,selected,type,params={},ranges={}){return modifyDocument(p,view,()=>{const result=[];for(const {o,edgeIds}of operationTargets(p,view,selected,ranges,true)){if(type==='rib'&&!o.closed&&!edgeIds.length)continue;o.modifiers??=[];if(type==='bend'&&o.modifiers.some(m=>m.type==='bend'))continue;const m=modifier(type,{...params,...(edgeIds.length?{edgeIds}:{}),...(type==='fabricFall'&&p.liveMirror&&o.symmetry?{symmetryScope:{axis:p.centerAxis??350}}:{}),operationId:uid()});if(type==='bend')o.modifiers.unshift(m);else o.modifiers.push(m);result.push({ownerId:o.id,modifierId:m.id});}return result;},{command:'modifier:'+type});}
export function constructionRefs(os,selected,contexts=[]){const result=[];for(const id of selected){const o=os.find(o=>o.id===id);if(o?.construction||o?.source&&!selected.includes(o.source))result.push({ownerId:id});}for(const ref of contexts)if(selected.includes(ref.ownerId)&&os.find(o=>o.id===ref.ownerId)?.modifiers?.some(m=>m.id===ref.modifierId))result.push(ref);return result;}
export function resolveRef(os,ref){const owner=os.find(o=>o.id===ref.ownerId);return {owner,value:ref.modifierId?owner?.modifiers?.find(m=>m.id===ref.modifierId):owner?.construction||owner};}
export function canonicalRefs(p,view,refs){const os=p.views[view],out=new Map();for(const ref of refs){let {owner,value}=resolveRef(os,ref);if(!value)continue;if(p.liveMirror){const master=os.find(o=>o.id===owner.instanceOf);if(master){owner=master;value=ref.modifierId?master.modifiers?.find(m=>m.id===ref.modifierId||value.operationId&&m.operationId===value.operationId):master.construction||master;}}if(value&&!value.locked)out.set(owner.id+':'+(ref.modifierId?value.id:''),{ownerId:owner.id,...(ref.modifierId?{modifierId:value.id}:{})});}return [...out.values()];}
export function removeConstructions(p,view,refs){return modifyDocument(p,view,()=>{const ids=new Set();for(const ref of canonicalRefs(p,view,refs)){const {owner,value}=resolveRef(p.views[view],ref);if(!value)continue;if(ref.modifierId)owner.modifiers=owner.modifiers.filter(m=>m.id!==value.id);else ids.add(owner.id);}p.views[view]=p.views[view].filter(o=>!ids.has(o.id));},{command:'construction:delete'});}
export function updateConstructions(p,view,refs,key,value){return modifyDocument(p,view,()=>{for(const ref of canonicalRefs(p,view,refs)){const {value:target}=resolveRef(p.views[view],ref);if(target)target[key]=value;}},{command:'construction:update'});}
export function stackTargets(p,view,selected,ranges={}){return operationTargets(p,view,selected,ranges).map(t=>({...t,edgeIds:t.edgeIds.length?t.edgeIds:[...(t.o.semanticEdges?.hem||t.o.semanticEdges?.cuff||(!t.o.closed?t.o.nodes.slice(0,-1).map(n=>n.edgeId):[]))]})).filter(t=>t.edgeIds.length);}
export function convertConstruction(p,view,ids,type,params={}){return modifyDocument(p,view,()=>{const converted=[];for(const {o} of operationTargets(p,view,ids)){if(o.closed||o.panelOf||o.component||o.source)continue;o.construction={...modifier(type),position:'centered',offset:0,width:o.width||.85,stroke:o.stroke,...params};delete o.construction.thickness;o.semanticType='construction';o.name=(type==='stitch'&&params.rows===2?'Costura doble':({stitch:'Costura',zipper:'Cierre',cord:'Cordón',piping:'Vivo',binding:'Bies',elastic:'Elástico'}[type]||type))+' '+String(p.views[view].filter(x=>x.construction?.type===type).length).padStart(2,'0');const stem=o.name.replace(/ \d+$/,'');let n=1;while(p.views[view].some(x=>x!==o&&x.name===stem+' '+String(n).padStart(2,'0')))n++;o.name=stem+' '+String(n).padStart(2,'0');converted.push(o.id);}return converted;},{command:'construction:convert'});}
